INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1813bf86-00e9-51a6-ada0-ff35b2664555', 'EU Corporate social responsibility (CSR) and its implementation into', 'Corporate social responsibility (CSR) and its implementation into EU Company law', 'This Study aims at providing an overview of national CSR policies and legislations within selected Member States (France, Germany, Italy, the Netherland, Poland and Spain), and an assessment of how these Member States have implemented European Union (EU)’s legislation and resolutions on CSR. The Study, therefore, aims at understanding to what extent Member States support the development and implementation of CSR strategies in the business community, whether CSR strategies are mandatory or voluntary and what enforcement mechanisms are foreseen.', 'This Study aims at providing an overview of national CSR policies and legislations within selected Member States (France, Germany, Italy, the Netherland, Poland and Spain), and an assessment of how these Member States have implemented European Union (EU)’s legislation and resolutions on CSR. The Study, therefore, aims at understanding to what extent Member States support the development and implementation of CSR strategies in the business community, whether CSR strategies are mandatory or voluntary and what enforcement mechanisms are foreseen.', 'This Study aims at providing an overview of national CSR policies and legislations within selected Member States (France, Germany, Italy, the Netherland, Poland and Spain), and an assessment of how these Member States have implemented European Union (EU)’s legislation and resolutions on CSR. The Study, therefore, aims at understanding to what extent Member States support the development and implementation of CSR strategies in the business community, whether CSR strategies are mandatory or voluntary and what enforcement mechanisms are foreseen.', 'EU', 'climate', 'in_force', '2020-01-01'::date, 'European Parliament', 'https://www.europarl.europa.eu/RegData/etudes/STUD/2020/658541/IPOL_STU(2020)658541_EN.pdf', ARRAY['other sustainability policy', 'regulations', 'sdg11', 'eu', 'sdg15', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5019dbd5-1f76-545d-9975-0b70a139d09d', 'Regulation (EU) on Climate Transition and Paris-Aligned Benchmarks', 'Regulation (EU) 2019/2089 on Climate Transition and Paris-Aligned Benchmarks and Sustainability-Related Disclosures for Benchmarks', 'Regulation (EU) 2019/2089 introduces provisions to establish EU Climate Transition Benchmarks and EU Paris-Aligned Benchmarks, aimed at aligning financial markets with the objectives of the Paris Agreement. The regulation defines minimum requirements for these benchmarks, ensuring transparency and comparability for investors while addressing greenwashing risks. It also mandates administrators to disclose the extent to which their benchmarks reflect Environmental, Social, and Governance (ESG) factors. Furthermore, it supports the development of decarbonization trajectories based on science-based targets and ensures methodological transparency, allowing users to assess contributions to climate-related goals effectively. This regulation amends Regulation (EU) 2016/1011 and aims to channel capital flows towards sustainable investments in alignment with the European Green Deal.', 'Regulation (EU) 2019/2089 introduces provisions to establish EU Climate Transition Benchmarks and EU Paris-Aligned Benchmarks, aimed at aligning financial markets with the objectives of the Paris Agreement. The regulation defines minimum requirements for these benchmarks, ensuring transparency and comparability for investors while addressing greenwashing risks. It also mandates administrators to disclose the extent to which their benchmarks reflect Environmental, Social, and Governance (ESG) factors. Furthermore, it supports the development of decarbonization trajectories based on science-based targets and ensures methodological transparency, allowing users to assess contributions to climate-related goals effectively. This regulation amends Regulation (EU) 2016/1011 and aims to channel capital flows towards sustainable investments in alignment with the European Green Deal.', 'Regulation (EU) 2019/2089 introduces provisions to establish EU Climate Transition Benchmarks and EU Paris-Aligned Benchmarks, aimed at aligning financial markets with the objectives of the Paris Agreement. The regulation defines minimum requirements for these benchmarks, ensuring transparency and comparability for investors while addressing greenwashing risks. It also mandates administrators to disclose the extent to which their benchmarks reflect Environmental, Social, and Governance (ESG) factors. Furthermore, it supports the development of decarbonization trajectories based on science-based targets and ensures methodological transparency, allowing users to assess contributions to climate-related goals effectively. This regulation amends Regulation (EU) 2016/1011 and aims to channel capital flows towards sustainable investments in alignment with the European Green Deal.', 'EU', 'climate', 'in_force', '2019-01-01'::date, 'CSSF', 'https://www.cssf.lu/en/Document/regulation-eu-2019-2089-of-the-european-parliament-and-of-the-council-of-27-november-2019/', ARRAY['sdg13', 'regulations', 'sdg7', 'mandatory', 'sdg16', 'disclosure', 'eu']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bf2b0bff-2c39-58f4-85e0-68a7e9a86b51', 'Regulation (EU) on sustainability-related disclosures in the financial', 'Regulation (EU) 2019/2088 on sustainability-related disclosures in the financial services sector (SFDR)', 'Regulation (EU) 2019/2088, commonly referred to as the Sustainable Finance Disclosure Regulation (SFDR), establishes harmonized disclosure requirements for financial market participants and advisers regarding sustainability risks, adverse sustainability impacts, and the promotion of sustainable investment objectives. The regulation aims to address information asymmetries between financial entities and end investors, fostering transparency and enabling informed investment decisions aligned with environmental, social, and governance (ESG) principles. Core provisions include website disclosures, pre-contractual transparency, and periodic reporting on sustainability factors. The SFDR enhances comparability across the EU''s internal market, reduces fragmentation, and promotes consistent application of sustainability standards in financial services. It is applicable to a wide range of entities, including asset managers, insurance companies, and pension providers, among others.', 'Regulation (EU) 2019/2088, commonly referred to as the Sustainable Finance Disclosure Regulation (SFDR), establishes harmonized disclosure requirements for financial market participants and advisers regarding sustainability risks, adverse sustainability impacts, and the promotion of sustainable investment objectives. The regulation aims to address information asymmetries between financial entities and end investors, fostering transparency and enabling informed investment decisions aligned with environmental, social, and governance (ESG) principles. Core provisions include website disclosures, pre-contractual transparency, and periodic reporting on sustainability factors. The SFDR enhances comparability across the EU''s internal market, reduces fragmentation, and promotes consistent application of sustainability standards in financial services. It is applicable to a wide range of entities, including asset managers, insurance companies, and pension providers, among others.', 'Regulation (EU) 2019/2088, commonly referred to as the Sustainable Finance Disclosure Regulation (SFDR), establishes harmonized disclosure requirements for financial market participants and advisers regarding sustainability risks, adverse sustainability impacts, and the promotion of sustainable investment objectives. The regulation aims to address information asymmetries between financial entities and end investors, fostering transparency and enabling informed investment decisions aligned with environmental, social, and governance (ESG) principles. Core provisions include website disclosures, pre-contractual transparency, and periodic reporting on sustainability factors. The SFDR enhances comparability across the EU''s internal market, reduces fragmentation, and promotes consistent application of sustainability standards in financial services. It is applicable to a wide range of entities, including asset managers, insurance companies, and pension providers, among others.', 'EU', 'climate', 'in_force', '2019-01-01'::date, 'Climate Laws', 'https://climate-laws.org/document/regulation-eu-2019-2088-on-sustainability-related-disclosures-in-the-financial-services-sector-and-amending-regulation-2020-852-taxonomy_eb3b', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'eu', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4664c7cb-65c6-50e5-9038-10ae1c31165e', 'pan-European personal pensioin product (PEPP)', 'Framework for a pan-European personal pensioin product (PEPP)', 'The aim of the proposed framework for a pan-European personal pension product (PEPP) is to encourage the development of personal (voluntary, individually funded) pensions in Europe, to support retirement saving and strengthen the single market for capital by making more funds available for investment.', 'The aim of the proposed framework for a pan-European personal pension product (PEPP) is to encourage the development of personal (voluntary, individually funded) pensions in Europe, to support retirement saving and strengthen the single market for capital by making more funds available for investment.', 'The aim of the proposed framework for a pan-European personal pension product (PEPP) is to encourage the development of personal (voluntary, individually funded) pensions in Europe, to support retirement saving and strengthen the single market for capital by making more funds available for investment.', 'EU', 'climate', 'in_force', '2019-01-01'::date, 'European Union', 'https://www.carrotsandsticks.org/policies/308_19', ARRAY['eu', 'voluntary_frameworks', 'voluntary', 'other sustainability policy']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('42126b6f-1f31-58eb-8509-40109c794722', 'EU Final Report Guidelines on Disclosure Requirements Applicable', 'Final Report Guidelines on Disclosure Requirements Applicable to Credit Ratings', 'This document includes a number of disclosure requirements relating to credit ratings. The purpose of these requirements is to ensure a sufficient level of transparency around the credit rating actions so as to enable the users of the credit rating to understand the main reasons for the credit rating, any limits or uncertainties underpinning the credit rating as well as where further information can be found to facilitate their own due diligence.', 'This document includes a number of disclosure requirements relating to credit ratings. The purpose of these requirements is to ensure a sufficient level of transparency around the credit rating actions so as to enable the users of the credit rating to understand the main reasons for the credit rating, any limits or uncertainties underpinning the credit rating as well as where further information can be found to facilitate their own due diligence.', 'This document includes a number of disclosure requirements relating to credit ratings. The purpose of these requirements is to ensure a sufficient level of transparency around the credit rating actions so as to enable the users of the credit rating to understand the main reasons for the credit rating, any limits or uncertainties underpinning the credit rating as well as where further information can be found to facilitate their own due diligence.', 'EU', 'climate', 'in_force', '2019-01-01'::date, 'European Securities and Markets Authority', 'https://www.esma.europa.eu/sites/default/files/library/esma33-9-320_final_report_guidelines_on_disclosure_requirements_applicable_to_credit_rating_agencies.pdf', ARRAY['guidance_frameworks', 'other sustainability policy', 'mandatory', 'sdg16', 'eu']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('56acfa38-0d90-528f-8f01-bc448cc45ae9', 'European Green Deal', 'The European Green Deal', 'The European Green Deal is the EU’s growth strategy to achieve climate neutrality by 2050, ensuring a sustainable economy while promoting social fairness and economic competitiveness. It provides a roadmap for deep transformations across energy, industry, transport, agriculture, biodiversity, and finance, aligning EU policies with the Paris Agreement and the Sustainable Development Goals (SDGs).

Key provisions include:

Climate Ambition & Carbon Neutrality:
The EU Climate Law enshrines net-zero emissions by 2050.
Carbon pricing & emissions trading are key mechanisms for reducing pollution.
Clean Energy Transition:
Decarbonization of the energy sector through renewable energy expansion and energy efficiency targets.
Sustainable Industry & Circular Economy:
Circular Economy Action Plan promotes eco-design, waste reduction, and sustainable raw material use.
Transport & Mobility:
Targets a 90% reduction in transport emissions through green fuels, electrification, and multimodal transport.
Sustainable Food System ("Farm to Fork" Strategy):
Promotes sustainable agriculture, reduction of pesticides, and biodiversity restoration.
Biodiversity & Zero Pollution Ambition:
Strengthens protected areas, afforestation, and restoration of ecosystems.
Sets targets for air, water, and soil pollution reduction.
Green Finance & Investment:
Establishes a Sustainable Finance Taxonomy to direct investments toward green activities.
Proposes the Just Transition Mechanism to assist regions transitioning away from fossil fuels.
The Green Deal integrates sustainability into all EU policies, ensuring a fair transition for workers, businesses, and citizens.', 'The European Green Deal is the EU’s growth strategy to achieve climate neutrality by 2050, ensuring a sustainable economy while promoting social fairness and economic competitiveness. It provides a roadmap for deep transformations across energy, industry, transport, agriculture, biodiversity, and finance, aligning EU policies with the Paris Agreement and the Sustainable Development Goals (SDGs).

Key provisions include:

