INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('24ddfc6e-020f-59f1-a872-0c69e4e02b11', 'EU Core Corporate Governance Issues - A comparative overview', 'Core Corporate Governance Issues - A comparative overview', 'This comparative overview of corporate governance issues focuses on certain corporate governance aspects which directors of listed companies on the one hand and directors of financial institutions (independent of their legal form), on the other hand, are subject to.', 'This comparative overview of corporate governance issues focuses on certain corporate governance aspects which directors of listed companies on the one hand and directors of financial institutions (independent of their legal form), on the other hand, are subject to.', 'This comparative overview of corporate governance issues focuses on certain corporate governance aspects which directors of listed companies on the one hand and directors of financial institutions (independent of their legal form), on the other hand, are subject to.', 'EU', 'governance', 'in_force', '2011-01-01'::date, 'IFC', 'https://www.ifc.org/content/dam/ifc/doc/mgrt/cg-practices-in-eu-guide.pdf', ARRAY['voluntary_frameworks', 'other sustainability policy', 'sdg16', 'eu', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
