INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('76ae0b93-288b-5ecc-9103-a6ee09d0c20d', 'EU Making sustainable consumption and production a reality', 'Making sustainable consumption and production a reality', 'This guide shows how a life cycle approach can be used to identify and reduce the environmental and health impacts of the products we use. It underlines the importance of considering these issues across the entire life cycle of a product and sets them within the context of policy development, business design and innovation.', 'This guide shows how a life cycle approach can be used to identify and reduce the environmental and health impacts of the products we use. It underlines the importance of considering these issues across the entire life cycle of a product and sets them within the context of policy development, business design and innovation.', 'This guide shows how a life cycle approach can be used to identify and reduce the environmental and health impacts of the products we use. It underlines the importance of considering these issues across the entire life cycle of a product and sets them within the context of policy development, business design and innovation.', 'EU', 'climate', 'in_force', '2010-01-01'::date, 'CSCP', 'https://www.cscp.org/wp-content/uploads/2016/05/39_CSCP__2011__-_SCP_Policies_A_Guide_for_CSO_en.pdf', ARRAY['sdg3', 'other sustainability policy', 'regulations', 'sdg12', 'eu', 'sdg9', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
