INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('200df940-aa50-5905-9d5e-75a951367507', 'Regulation (EC) of the European Parliament and', 'Regulation (EC) No 166/2006 of the European Parliament and of the Council of 18 January 2006 concerning the establishment of a European Pollutant Release and Transfer Register and emdning Council Directives 91/689/EEC and 96/61/EC', 'This document is concerned with the Regulation (EC) No 166/2006 of the European Parliament and of the Council of 18 January 2006 concerning the establishment of a European Pollutant Release and Transfer Register and emdning Council Directives 91/689/EEC and 96/61/EC.', 'This document is concerned with the Regulation (EC) No 166/2006 of the European Parliament and of the Council of 18 January 2006 concerning the establishment of a European Pollutant Release and Transfer Register and emdning Council Directives 91/689/EEC and 96/61/EC.', 'This document is concerned with the Regulation (EC) No 166/2006 of the European Parliament and of the Council of 18 January 2006 concerning the establishment of a European Pollutant Release and Transfer Register and emdning Council Directives 91/689/EEC and 96/61/EC.', 'EU', 'governance', 'in_force', '2006-01-01'::date, 'legislation.gov.uk', 'https://www.legislation.gov.uk/eur/2006/166/contents', ARRAY['eu', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a826e1bc-baeb-56f5-a763-21324ad4c8bc', 'Directive – Establishing the EU Emissions Trading System', 'Directive 2003/87/EC – Establishing the EU Emissions Trading System (EU ETS)', 'The EU ETS Directive (2003/87/EC) establishes a greenhouse gas (GHG) emissions trading system within the EU. The system follows a cap-and-trade approach, setting a limit on total emissions while allowing companies to buy and sell emission allowances. The goal is to reduce carbon emissions cost-effectively and align with EU climate neutrality objectives. The directive has undergone multiple amendments to expand its scope and align with the Paris Agreement.

Key provisions include:

Scope & Applicability:
Covers power generation, industrial sectors, aviation, and maritime transport.
Applies to installations emitting CO₂, N₂O, and PFCs.
Cap-and-Trade System:
Sets a declining cap on total GHG emissions across the EU.
Companies receive or purchase emission allowances, which they can trade.
Phases & Free Allocation of Allowances:
Phase 1 (2005-2007) – Pilot phase with free allocation.
Phase 2 (2008-2012) – Aligned with Kyoto Protocol, introduced auctioning.
Phase 3 (2013-2020) – Expanded coverage, reduced free allowances.
Phase 4 (2021-2030) – Stronger emission reduction targets (55% by 2030).
Auctioning & Market Stability Mechanism:
A Market Stability Reserve (MSR) adjusts the supply of allowances to prevent price volatility.
100% auctioning for power sector, with partial free allocation for industry.
Inclusion of Aviation & Maritime Transport:
Aviation emissions regulated since 2012, with allowances allocated for EU flights.
Maritime transport added in 2024, covering 50% of emissions from international voyages.
Penalties & Compliance:
Companies exceeding allowances must purchase additional permits or face fines (€100 per excess tonne).
The EU ETS is a cornerstone of the EU Green Deal and Fit for 55 Package, aiming for climate neutrality by 2050.', 'The EU ETS Directive (2003/87/EC) establishes a greenhouse gas (GHG) emissions trading system within the EU. The system follows a cap-and-trade approach, setting a limit on total emissions while allowing companies to buy and sell emission allowances. The goal is to reduce carbon emissions cost-effectively and align with EU climate neutrality objectives. The directive has undergone multiple amendments to expand its scope and align with the Paris Agreement.

