INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('61ddd442-acf3-58c7-8ccf-d07ab302495e', 'EU Directive amending Directives on annual and consolidated', 'EU Directive 2003/51/EC amending Directives on annual and consolidated accounts of companies, banks, financial institutions, and insurance undertakings', 'This document is concerned with the Directive 2003/51/EC of the European Parliament and of the Council of 18 June 2003 amending Directives 78/660/EEC, 83/349/EEC, 86/635/EEC  and 91/674/EEC on the annual and consolidated accounts of certain types of companies, banks and other financial institutions and insurance undertakings.', 'This document is concerned with the Directive 2003/51/EC of the European Parliament and of the Council of 18 June 2003 amending Directives 78/660/EEC, 83/349/EEC, 86/635/EEC  and 91/674/EEC on the annual and consolidated accounts of certain types of companies, banks and other financial institutions and insurance undertakings.', 'This document is concerned with the Directive 2003/51/EC of the European Parliament and of the Council of 18 June 2003 amending Directives 78/660/EEC, 83/349/EEC, 86/635/EEC  and 91/674/EEC on the annual and consolidated accounts of certain types of companies, banks and other financial institutions and insurance undertakings.', 'EU', 'governance', 'in_force', '2003-01-01'::date, 'EUR-Lex', 'http://data.europa.eu/eli/dir/2003/51/oj/slv', ARRAY['eu', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bfc8cb64-00c1-59eb-86a6-3d706f319502', 'EU Commission Recommendation of 30 May 2001 on the', 'Commission Recommendation of 30 May 2001 on the recognition, measurement and disclosure of environmental issues in the annual accounts and annual reports of companies', 'This recommendation is limited to information provided in the annual and consolidated accounts and in the annual reports and consolidated annual reports of companies with regard to environmental issues. It does not deal with special purpose reporting, such as environmental reports, except where it is considered appropriate to relate annual accounts, annual reports and separate environmental reports with a view to making their information content consistent.', 'This recommendation is limited to information provided in the annual and consolidated accounts and in the annual reports and consolidated annual reports of companies with regard to environmental issues. It does not deal with special purpose reporting, such as environmental reports, except where it is considered appropriate to relate annual accounts, annual reports and separate environmental reports with a view to making their information content consistent.', 'This recommendation is limited to information provided in the annual and consolidated accounts and in the annual reports and consolidated annual reports of companies with regard to environmental issues. It does not deal with special purpose reporting, such as environmental reports, except where it is considered appropriate to relate annual accounts, annual reports and separate environmental reports with a view to making their information content consistent.', 'EU', 'climate', 'in_force', '2001-01-01'::date, 'Publications Office of the EU', 'https://op.europa.eu/mt/publication-detail/-/publication/1a83bbcd-33b0-4b27-8aaf-38d1225b02f7', ARRAY['eu', 'guidance_frameworks', 'voluntary', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('46e33c67-3e37-5759-9f21-287bf33c09cc', 'Green Paper Promoting a European framework for Corporate', 'Green Paper Promoting a European framework for Corporate Social Responsibility', 'This Green Paper aims to launch a wide debate on how the European Union could promote corporate social responsibility at both the European and international level, in particular on how to make the most of existing experiences, to encourage the development of innovative practices, to bring greater transparency and to increase the reliability of evaluation and validation. It suggests an approach based on the deepening of partnerships in which all actors have an active role to play.', 'This Green Paper aims to launch a wide debate on how the European Union could promote corporate social responsibility at both the European and international level, in particular on how to make the most of existing experiences, to encourage the development of innovative practices, to bring greater transparency and to increase the reliability of evaluation and validation. It suggests an approach based on the deepening of partnerships in which all actors have an active role to play.', 'This Green Paper aims to launch a wide debate on how the European Union could promote corporate social responsibility at both the European and international level, in particular on how to make the most of existing experiences, to encourage the development of innovative practices, to bring greater transparency and to increase the reliability of evaluation and validation. It suggests an approach based on the deepening of partnerships in which all actors have an active role to play.', 'EU', 'governance', 'in_force', '2001-01-01'::date, 'European Commission', 'https://ec.europa.eu/commission/presscorner/api/files/document/print/en/doc_01_9/DOC_01_9_EN.pdf', ARRAY['sdg17', 'voluntary', 'sdg16', 'disclosure', 'eu', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
