INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('edf05618-0d09-5622-8581-b18a56f0476b', 'Proposal for a Regulation of the European Parliament', 'Proposal for a Regulation of the European Parliament and of the Council establishing a framework for setting ecodesign requirements for sustainable products and repealing Directive 2009/125/EC', 'This policy was published in 2022 by European Union (EU). It addresses sustainability and corporate responsibility requirements.', 'This policy was published in 2022 by European Union (EU). It addresses sustainability and corporate responsibility requirements.', 'This policy was published in 2022 by European Union (EU). It addresses sustainability and corporate responsibility requirements.', 'EU', 'climate', 'in_force', '2022-01-01'::date, 'Irish Government (enterprise.gov.ie)', 'https://enterprise.gov.ie/en/what-we-do/the-business-environment/ecodesign-for-sustainable-products/', ARRAY['sdg13', 'regulations', 'mandatory', 'sdg16', 'sdg12', 'eu']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7df50432-d9b6-572f-97a8-9bbfe344d6ff', 'Fiji Climate Change Bill 2021 (Bill of', 'Climate Change Bill 2021 (Bill No 31 of 2021)', 'The Fiji Climate Change Bill 2021 is a comprehensive legislation aimed at addressing climate change in Fiji. The Bill sets out a framework for the country to mitigate and adapt to the impacts of climate change, and establishes institutional arrangements for the implementation of climate change policies and programs. Regarding companies, the Bill requires companies to report on their greenhouse gas emissions and measures to mitigate them. This reporting requirement applies to companies operating in Fiji whose annual greenhouse gas emissions exceed a certain threshold, which will be determined by the government through regulations. Furthermore, the Bill establishes a Climate Change Trust Fund, which will be funded by a levy on companies operating in Fiji that exceed a certain threshold of greenhouse gas emissions. The fund will finance climate change adaptation and mitigation programs, including those undertaken by the private sector. In summary, the Fiji Climate Change Bill 2021 places significant responsibilities on companies operating in Fiji to report on their greenhouse gas emissions and contribute to the Climate Change Trust Fund, which will support climate change mitigation and adaptation programs in Fiji.', 'The Fiji Climate Change Bill 2021 is a comprehensive legislation aimed at addressing climate change in Fiji. The Bill sets out a framework for the country to mitigate and adapt to the impacts of climate change, and establishes institutional arrangements for the implementation of climate change policies and programs. Regarding companies, the Bill requires companies to report on their greenhouse gas emissions and measures to mitigate them. This reporting requirement applies to companies operating in Fiji whose annual greenhouse gas emissions exceed a certain threshold, which will be determined by the government through regulations. Furthermore, the Bill establishes a Climate Change Trust Fund, which will be funded by a levy on companies operating in Fiji that exceed a certain threshold of greenhouse gas emissions. The fund will finance climate change adaptation and mitigation programs, including those undertaken by the private sector. In summary, the Fiji Climate Change Bill 2021 places significant responsibilities on companies operating in Fiji to report on their greenhouse gas emissions and contribute to the Climate Change Trust Fund, which will support climate change mitigation and adaptation programs in Fiji.', 'The Fiji Climate Change Bill 2021 is a comprehensive legislation aimed at addressing climate change in Fiji. The Bill sets out a framework for the country to mitigate and adapt to the impacts of climate change, and establishes institutional arrangements for the implementation of climate change policies and programs. Regarding companies, the Bill requires companies to report on their greenhouse gas emissions and measures to mitigate them. This reporting requirement applies to companies operating in Fiji whose annual greenhouse gas emissions exceed a certain threshold, which will be determined by the government through regulations. Furthermore, the Bill establishes a Climate Change Trust Fund, which will be funded by a levy on companies operating in Fiji that exceed a certain threshold of greenhouse gas emissions. The fund will finance climate change adaptation and mitigation programs, including those undertaken by the private sector. In summary, the Fiji Climate Change Bill 2021 places significant responsibilities on companies operating in Fiji to report on their greenhouse gas emissions and contribute to the Climate Change Trust Fund, which will support climate change mitigation and adaptation programs in Fiji.', 'Fiji', 'climate', 'in_force', '2021-01-01'::date, 'Fiji', 'https://www.carrotsandsticks.org/policies/56_2', ARRAY['sdg4', 'sdg13', 'sdg14', 'regulations', 'sdg7', 'sdg11', 'mandatory', 'fiji', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('86563863-31c0-5d4f-adba-dd1db5850934', 'Fiji Low Emission Development Strategy', 'Fiji Low Emission Development Strategy 2018-2050', 'The Fiji Low Emission Development Strategy (LEDS) 2018-2050 shall be considered a “living” document in that information expressed in this publication represents the Fijian Government’s current understanding of greenhouse gas (GHG) emissions from relevant sectors and current understanding of mitigation actions (including technology, finance, capacity building, and technical assistance needs), which can contribute to meeting the GHG reductions articulated in
the four scenarios presented. The Fijian Government reserves the
right to periodically update the Fiji LEDS, as may be needed, to ensure validity, transparency, and accuracy over time. Most notably, the Fijian Government understands that not all data relating to GHG emissions from the different sectors in the LEDS are currently fully known, nor are all mitigation actions fully investigated. As such, the collection of additional data and the inclusion of new or improved technology, and its costs over time, will have an impact on future national planning.', 'The Fiji Low Emission Development Strategy (LEDS) 2018-2050 shall be considered a “living” document in that information expressed in this publication represents the Fijian Government’s current understanding of greenhouse gas (GHG) emissions from relevant sectors and current understanding of mitigation actions (including technology, finance, capacity building, and technical assistance needs), which can contribute to meeting the GHG reductions articulated in
