INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('14695195-4127-546b-84d1-7a7fd467cd4c', 'Finland Proposal of the working group preparing the implementation', 'Proposal of the working group preparing the implementation of the Pay Transparency Directive for a draft government proposal to Parliament on amending the Act on Equality between Women and Men, Section 2 of the Act on the Equality Ombudsman, the Act on Statistics Finland, the Act on the Income Information System and Section 1 of the Act on the Enforcement of Fines', 'This Finnish policy proposal aims to implement the Pay Transparency Directive by amending laws on gender equality, the Equality Ombudsman, statistics, income information, and fines enforcement. It focuses on strengthening equal pay principles through transparency and enforcement mechanisms, primarily benefiting employees, employers, and government bodies.', 'This Finnish policy proposal aims to implement the Pay Transparency Directive by amending laws on gender equality, the Equality Ombudsman, statistics, income information, and fines enforcement. It focuses on strengthening equal pay principles through transparency and enforcement mechanisms, primarily benefiting employees, employers, and government bodies.', 'This Finnish policy proposal aims to implement the Pay Transparency Directive by amending laws on gender equality, the Equality Ombudsman, statistics, income information, and fines enforcement. It focuses on strengthening equal pay principles through transparency and enforcement mechanisms, primarily benefiting employees, employers, and government bodies.', 'Finland', 'nature', 'in_force', '2025-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_31', ARRAY['regulations', 'mandatory', 'sdg5', 'sdg16', 'sdg15', 'finland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d49cbf66-0d30-5313-836b-78baee5c1908', 'Finland Auditing Act', 'Auditing Act', 'The Auditing Act of Finland, updated in 2025, outlines regulations for auditing financial statements of entities and organizations. It specifies requirements for auditors and applies to both public and private sector audits, excluding state audit activities. The Act aims to ensure compliance and transparency in financial reporting.', 'The Auditing Act of Finland, updated in 2025, outlines regulations for auditing financial statements of entities and organizations. It specifies requirements for auditors and applies to both public and private sector audits, excluding state audit activities. The Act aims to ensure compliance and transparency in financial reporting.', 'The Auditing Act of Finland, updated in 2025, outlines regulations for auditing financial statements of entities and organizations. It specifies requirements for auditors and applies to both public and private sector audits, excluding state audit activities. The Act aims to ensure compliance and transparency in financial reporting.', 'Finland', 'climate', 'in_force', '2025-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_35', ARRAY['regulations', 'mandatory', 'sdg16', 'sdg15', 'finland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ccc90410-262e-5890-a1d4-e121192ded79', 'Finland Act amending the entry into force provision', 'Act amending the entry into force provision of the Act amending the Accounting Act', 'The policy document amends the entry into force provisions of the Accounting Act in Finland. It allows large companies and parent companies of large groups to prepare their management reports without the required sustainability report until the fiscal years beginning on or after January 1, 2027. Legal entities are granted similar exemptions until January 1, 2028. The law will come into effect on December 1, 2025, and applies to fiscal years starting on or after January 1, 2026, with potential application to earlier fiscal years that began on or after January 1, 2025. This is a mandatory requirement for specified entities.', 'The policy document amends the entry into force provisions of the Accounting Act in Finland. It allows large companies and parent companies of large groups to prepare their management reports without the required sustainability report until the fiscal years beginning on or after January 1, 2027. Legal entities are granted similar exemptions until January 1, 2028. The law will come into effect on December 1, 2025, and applies to fiscal years starting on or after January 1, 2026, with potential application to earlier fiscal years that began on or after January 1, 2025. This is a mandatory requirement for specified entities.', 'The policy document amends the entry into force provisions of the Accounting Act in Finland. It allows large companies and parent companies of large groups to prepare their management reports without the required sustainability report until the fiscal years beginning on or after January 1, 2027. Legal entities are granted similar exemptions until January 1, 2028. The law will come into effect on December 1, 2025, and applies to fiscal years starting on or after January 1, 2026, with potential application to earlier fiscal years that began on or after January 1, 2025. This is a mandatory requirement for specified entities.', 'Finland', 'climate', 'in_force', '2025-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_42', ARRAY['regulations', 'mandatory', 'disclosure', 'sdg15', 'finland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ec84dec5-ee32-53a3-960f-3095e3cf833e', 'Finland Act amending the Maritime Environmental Protection Act', 'Act amending the Maritime Environmental Protection Act', 'The Act amending the Maritime Environmental Protection Act in Finland aims to prevent pollution from ships by regulating emissions and waste disposal. It updates legal provisions to align with international obligations, particularly focusing on marine fuel usage, waste management, and monitoring greenhouse gas emissions from ships. Targeted at the maritime industry and enforcement agencies.', 'The Act amending the Maritime Environmental Protection Act in Finland aims to prevent pollution from ships by regulating emissions and waste disposal. It updates legal provisions to align with international obligations, particularly focusing on marine fuel usage, waste management, and monitoring greenhouse gas emissions from ships. Targeted at the maritime industry and enforcement agencies.', 'The Act amending the Maritime Environmental Protection Act in Finland aims to prevent pollution from ships by regulating emissions and waste disposal. It updates legal provisions to align with international obligations, particularly focusing on marine fuel usage, waste management, and monitoring greenhouse gas emissions from ships. Targeted at the maritime industry and enforcement agencies.', 'Finland', 'climate', 'in_force', '2024-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_34', ARRAY['sdg13', 'sdg14', 'regulations', 'sdg9', 'mandatory', 'sdg12', 'sdg15', 'finland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8397a7fd-01cd-54b4-8139-e894f458404c', 'Finland requirements for the approval of auditors ()', 'Regulation on the requirements for the approval of auditors (392/2024)', 'The Regulation on the requirements for the approval of auditors (392/2024) in Finland establishes mandatory educational and practical experience requirements for individuals seeking to become approved auditors. It applies to both HT (Authorized) and JHT (Public Sector) auditors, outlining specific coursework in auditing, accounting, business, and law, including sustainability reporting. Applicants must demonstrate a minimum level of education and relevant work experience. The regulation aims to ensure that auditors possess the necessary qualifications to uphold auditing standards in Finland.', 'The Regulation on the requirements for the approval of auditors (392/2024) in Finland establishes mandatory educational and practical experience requirements for individuals seeking to become approved auditors. It applies to both HT (Authorized) and JHT (Public Sector) auditors, outlining specific coursework in auditing, accounting, business, and law, including sustainability reporting. Applicants must demonstrate a minimum level of education and relevant work experience. The regulation aims to ensure that auditors possess the necessary qualifications to uphold auditing standards in Finland.', 'The Regulation on the requirements for the approval of auditors (392/2024) in Finland establishes mandatory educational and practical experience requirements for individuals seeking to become approved auditors. It applies to both HT (Authorized) and JHT (Public Sector) auditors, outlining specific coursework in auditing, accounting, business, and law, including sustainability reporting. Applicants must demonstrate a minimum level of education and relevant work experience. The regulation aims to ensure that auditors possess the necessary qualifications to uphold auditing standards in Finland.', 'Finland', 'climate', 'in_force', '2024-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_40', ARRAY['sdg4', 'regulations', 'mandatory', 'disclosure', 'sdg15', 'finland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('673b554f-9a5a-549d-a572-ca83a1650c39', 'Finland Act amending Chapters 1 and 7 of the', 'Act amending Chapters 1 and 7 of the Accounting Act (605/2024)', 'The Act amending Chapters 1 and 7 of the Accounting Act (605/2024) in Finland establishes new regulations for sustainability reporting, specifically targeting large companies, parent companies of large groups, publicly listed small and medium enterprises. It mandates that these entities prepare a sustainability report according to specified standards, which includes information on their operations and compliance with sustainability reporting standards. The law is applicable from January 1, 2025, and aims to enhance transparency in corporate sustainability practices. It is a mandatory requirement for the specified entities.', 'The Act amending Chapters 1 and 7 of the Accounting Act (605/2024) in Finland establishes new regulations for sustainability reporting, specifically targeting large companies, parent companies of large groups, publicly listed small and medium enterprises. It mandates that these entities prepare a sustainability report according to specified standards, which includes information on their operations and compliance with sustainability reporting standards. The law is applicable from January 1, 2025, and aims to enhance transparency in corporate sustainability practices. It is a mandatory requirement for the specified entities.', 'The Act amending Chapters 1 and 7 of the Accounting Act (605/2024) in Finland establishes new regulations for sustainability reporting, specifically targeting large companies, parent companies of large groups, publicly listed small and medium enterprises. It mandates that these entities prepare a sustainability report according to specified standards, which includes information on their operations and compliance with sustainability reporting standards. The law is applicable from January 1, 2025, and aims to enhance transparency in corporate sustainability practices. It is a mandatory requirement for the specified entities.', 'Finland', 'climate', 'in_force', '2024-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_41', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'sdg15', 'finland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('952bb321-c2af-5868-a244-28a8b245ebf6', 'Finland Amendments to the Accounting Act ()', 'Amendments to the Accounting Act (1249/2023)', 'The Amendments to the Accounting Act (1249/2023) in Finland establish mandatory accounting obligations for various legal entities, including companies, associations, and certain foreign entities operating in Finland. The act specifies requirements for bookkeeping, financial reporting, and compliance with good accounting practices. It applies to all businesses that meet certain thresholds regarding total assets, revenue, or employee count. The amendments aim to enhance transparency and accountability in financial reporting. The regulations are mandatory for the entities defined within the act.', 'The Amendments to the Accounting Act (1249/2023) in Finland establish mandatory accounting obligations for various legal entities, including companies, associations, and certain foreign entities operating in Finland. The act specifies requirements for bookkeeping, financial reporting, and compliance with good accounting practices. It applies to all businesses that meet certain thresholds regarding total assets, revenue, or employee count. The amendments aim to enhance transparency and accountability in financial reporting. The regulations are mandatory for the entities defined within the act.', 'The Amendments to the Accounting Act (1249/2023) in Finland establish mandatory accounting obligations for various legal entities, including companies, associations, and certain foreign entities operating in Finland. The act specifies requirements for bookkeeping, financial reporting, and compliance with good accounting practices. It applies to all businesses that meet certain thresholds regarding total assets, revenue, or employee count. The amendments aim to enhance transparency and accountability in financial reporting. The regulations are mandatory for the entities defined within the act.', 'Finland', 'climate', 'in_force', '2023-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_36', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'sdg15', 'finland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9155f870-f480-5191-9316-26ba6d99ba8f', 'Finland Limited Liability Companies Act ()', 'Limited Liability Companies Act (1252/2023)', 'The Limited Liability Companies Act (1252/2023) establishes the legal framework for all limited liability companies registered in Finland. It outlines key principles such as the separation of legal personality, shareholder liability, and governance structures. The Act mandates that companies must operate for profit unless stated otherwise in their articles of association. It applies to both private and public companies and includes provisions for share transferability and corporate governance. Compliance with this Act is mandatory for all registered limited liability companies in Finland.', 'The Limited Liability Companies Act (1252/2023) establishes the legal framework for all limited liability companies registered in Finland. It outlines key principles such as the separation of legal personality, shareholder liability, and governance structures. The Act mandates that companies must operate for profit unless stated otherwise in their articles of association. It applies to both private and public companies and includes provisions for share transferability and corporate governance. Compliance with this Act is mandatory for all registered limited liability companies in Finland.', 'The Limited Liability Companies Act (1252/2023) establishes the legal framework for all limited liability companies registered in Finland. It outlines key principles such as the separation of legal personality, shareholder liability, and governance structures. The Act mandates that companies must operate for profit unless stated otherwise in their articles of association. It applies to both private and public companies and includes provisions for share transferability and corporate governance. Compliance with this Act is mandatory for all registered limited liability companies in Finland.', 'Finland', 'nature', 'in_force', '2023-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_37', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'sdg15', 'finland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('738a0b82-c35b-5542-8208-07a1601f1ddd', 'Finland Securities Markets Act ()', 'Securities Markets Act (1260/2023)', 'The Securities Markets Act (1260/2023) aims to ensure the stability of financial markets in Finland by regulating the activities of credit, insurance, and pension institutions. It mandates the Finnish Financial Supervisory Authority to oversee compliance with financial regulations, including international accounting and sustainability reporting standards. The Act applies to all entities operating within the financial markets and establishes requirements for licensing, monitoring, and reporting. Compliance with this Act is mandatory for the regulated entities.', 'The Securities Markets Act (1260/2023) aims to ensure the stability of financial markets in Finland by regulating the activities of credit, insurance, and pension institutions. It mandates the Finnish Financial Supervisory Authority to oversee compliance with financial regulations, including international accounting and sustainability reporting standards. The Act applies to all entities operating within the financial markets and establishes requirements for licensing, monitoring, and reporting. Compliance with this Act is mandatory for the regulated entities.', 'The Securities Markets Act (1260/2023) aims to ensure the stability of financial markets in Finland by regulating the activities of credit, insurance, and pension institutions. It mandates the Finnish Financial Supervisory Authority to oversee compliance with financial regulations, including international accounting and sustainability reporting standards. The Act applies to all entities operating within the financial markets and establishes requirements for licensing, monitoring, and reporting. Compliance with this Act is mandatory for the regulated entities.', 'Finland', 'climate', 'in_force', '2023-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_38', ARRAY['regulations', 'mandatory', 'disclosure', 'sdg15', 'finland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e4b31eeb-e119-523f-8796-54122c1588b5', 'Finland Financial Supervisory Authority ()', 'Act on the Financial Supervisory Authority (1261/2023)', 'The Act on the Financial Supervisory Authority (1261/2023) aims to ensure the stability of the financial markets in Finland by regulating credit, insurance, and pension institutions. It mandates the Financial Supervisory Authority to oversee compliance with financial regulations, promote good practices, and safeguard the interests of insured parties. The Act applies to all entities operating within the financial markets and includes provisions for licensing, monitoring, and enforcing compliance with national and EU standards. This policy is mandatory for all relevant financial institutions.', 'The Act on the Financial Supervisory Authority (1261/2023) aims to ensure the stability of the financial markets in Finland by regulating credit, insurance, and pension institutions. It mandates the Financial Supervisory Authority to oversee compliance with financial regulations, promote good practices, and safeguard the interests of insured parties. The Act applies to all entities operating within the financial markets and includes provisions for licensing, monitoring, and enforcing compliance with national and EU standards. This policy is mandatory for all relevant financial institutions.', 'The Act on the Financial Supervisory Authority (1261/2023) aims to ensure the stability of the financial markets in Finland by regulating credit, insurance, and pension institutions. It mandates the Financial Supervisory Authority to oversee compliance with financial regulations, promote good practices, and safeguard the interests of insured parties. The Act applies to all entities operating within the financial markets and includes provisions for licensing, monitoring, and enforcing compliance with national and EU standards. This policy is mandatory for all relevant financial institutions.', 'Finland', 'nature', 'in_force', '2023-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_39', ARRAY['regulations', 'mandatory', 'disclosure', 'sdg15', 'finland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2c63f98b-967d-50a8-bd18-d4ff7a18b189', 'Finland Climate Act', '432/2022 Climate Act', 'The 432/2022 Climate Act in Finland outlines goals for climate policy planning and monitoring. It aims to reduce greenhouse gas emissions, engage the public and parliament in climate policy, and ensure compliance with international agreements. This law applies to state authorities in climate policy planning and implementation.', 'The 432/2022 Climate Act in Finland outlines goals for climate policy planning and monitoring. It aims to reduce greenhouse gas emissions, engage the public and parliament in climate policy, and ensure compliance with international agreements. This law applies to state authorities in climate policy planning and implementation.', 'The 432/2022 Climate Act in Finland outlines goals for climate policy planning and monitoring. It aims to reduce greenhouse gas emissions, engage the public and parliament in climate policy, and ensure compliance with international agreements. This law applies to state authorities in climate policy planning and implementation.', 'Finland', 'climate', 'in_force', '2022-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_33', ARRAY['sdg13', 'regulations', 'mandatory', 'sdg15', 'finland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7597c02e-6fef-5a10-86f2-0b54066b507d', 'Finland Legal report on corporate responsibility', 'Legal report on corporate responsibility 2021', 'Oikeudellinen selvitys yritysvastuulaista 2021 (Legal Review of the Corporate Liability Act 2021) is a report commissioned by the Finnish government to evaluate the feasibility and potential impacts of introducing a new corporate liability law in Finland. The report provides a legal analysis of the key features of the proposed legislation and its potential effects on companies operating in Finland. The proposed Corporate Liability Act would establish a framework for holding companies accountable for certain human rights violations and environmental harms caused by their operations or supply chains. The Act would apply to both Finnish companies and foreign companies operating in Finland. If passed, it will become a legal requirement for companies to comply with the due diligence measures and to be held accountable for certain human rights violations and environmental harms caused by their operations or supply chains. The report concludes that the proposed legislation is feasible and compatible with existing legal frameworks in Finland and the European Union. The report also suggests that the Act would have a significant impact on companies operating in Finland, particularly those in high-risk sectors such as mining, oil and gas, and textiles. Overall, the Oikeudellinen selvitys yritysvastuulaista 2021 provides a comprehensive legal analysis of the proposed Corporate Liability Act and its potential implications for companies operating in Finland. The report highlights the importance of addressing corporate responsibility for human rights and environmental harms, and suggests that the proposed legislation could be an effective tool for promoting sustainable and responsible business practices in Finland.', 'Oikeudellinen selvitys yritysvastuulaista 2021 (Legal Review of the Corporate Liability Act 2021) is a report commissioned by the Finnish government to evaluate the feasibility and potential impacts of introducing a new corporate liability law in Finland. The report provides a legal analysis of the key features of the proposed legislation and its potential effects on companies operating in Finland. The proposed Corporate Liability Act would establish a framework for holding companies accountable for certain human rights violations and environmental harms caused by their operations or supply chains. The Act would apply to both Finnish companies and foreign companies operating in Finland. If passed, it will become a legal requirement for companies to comply with the due diligence measures and to be held accountable for certain human rights violations and environmental harms caused by their operations or supply chains. The report concludes that the proposed legislation is feasible and compatible with existing legal frameworks in Finland and the European Union. The report also suggests that the Act would have a significant impact on companies operating in Finland, particularly those in high-risk sectors such as mining, oil and gas, and textiles. Overall, the Oikeudellinen selvitys yritysvastuulaista 2021 provides a comprehensive legal analysis of the proposed Corporate Liability Act and its potential implications for companies operating in Finland. The report highlights the importance of addressing corporate responsibility for human rights and environmental harms, and suggests that the proposed legislation could be an effective tool for promoting sustainable and responsible business practices in Finland.', 'Oikeudellinen selvitys yritysvastuulaista 2021 (Legal Review of the Corporate Liability Act 2021) is a report commissioned by the Finnish government to evaluate the feasibility and potential impacts of introducing a new corporate liability law in Finland. The report provides a legal analysis of the key features of the proposed legislation and its potential effects on companies operating in Finland. The proposed Corporate Liability Act would establish a framework for holding companies accountable for certain human rights violations and environmental harms caused by their operations or supply chains. The Act would apply to both Finnish companies and foreign companies operating in Finland. If passed, it will become a legal requirement for companies to comply with the due diligence measures and to be held accountable for certain human rights violations and environmental harms caused by their operations or supply chains. The report concludes that the proposed legislation is feasible and compatible with existing legal frameworks in Finland and the European Union. The report also suggests that the Act would have a significant impact on companies operating in Finland, particularly those in high-risk sectors such as mining, oil and gas, and textiles. Overall, the Oikeudellinen selvitys yritysvastuulaista 2021 provides a comprehensive legal analysis of the proposed Corporate Liability Act and its potential implications for companies operating in Finland. The report highlights the importance of addressing corporate responsibility for human rights and environmental harms, and suggests that the proposed legislation could be an effective tool for promoting sustainable and responsible business practices in Finland.', 'Finland', 'climate', 'in_force', '2021-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_30', ARRAY['sdg9', 'sdg7', 'mandatory', 'sdg16', 'mandatory_regulations', 'sdg12', 'disclosure', 'sdg15', 'finland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('77bb9916-4e53-5129-a243-b395761e16d0', 'Finland Finnish Corporate Governance Code', 'Finnish Corporate Governance Code 2020', 'The Corporate Governance Code preceding this New Corporate Governance Code 2020 entered into force on 1 January 2016. The regulatory framework relating to the governance of listed companies has changed since then. The central change underlying the revision of the Corporate Governance Code is the EU’s Second Shareholder Rights Directive 1, which has been implemented in Finnish national legislation on 10 June 2019. The Corporate Governance Code has been amended to correspond to the requirements of the new legislation, particularly with respect to the provisions concerning the remuneration policy and remuneration report.', 'The Corporate Governance Code preceding this New Corporate Governance Code 2020 entered into force on 1 January 2016. The regulatory framework relating to the governance of listed companies has changed since then. The central change underlying the revision of the Corporate Governance Code is the EU’s Second Shareholder Rights Directive 1, which has been implemented in Finnish national legislation on 10 June 2019. The Corporate Governance Code has been amended to correspond to the requirements of the new legislation, particularly with respect to the provisions concerning the remuneration policy and remuneration report.', 'The Corporate Governance Code preceding this New Corporate Governance Code 2020 entered into force on 1 January 2016. The regulatory framework relating to the governance of listed companies has changed since then. The central change underlying the revision of the Corporate Governance Code is the EU’s Second Shareholder Rights Directive 1, which has been implemented in Finnish national legislation on 10 June 2019. The Corporate Governance Code has been amended to correspond to the requirements of the new legislation, particularly with respect to the provisions concerning the remuneration policy and remuneration report.', 'Finland', 'climate', 'in_force', '2020-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_29', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'sdg9', 'finland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c1213435-c01c-559e-aaf5-6415c828daea', 'Finland Working Hours Act', '872/2019 Working Hours Act', 'The 872/2019 Working Hours Act in Finland outlines regulations for work hours, exemptions, and arrangements such as on-call duty. It applies to employees under various work contracts and aims to ensure fair working hours and conditions, with specific provisions for different sectors and job roles.', 'The 872/2019 Working Hours Act in Finland outlines regulations for work hours, exemptions, and arrangements such as on-call duty. It applies to employees under various work contracts and aims to ensure fair working hours and conditions, with specific provisions for different sectors and job roles.', 'The 872/2019 Working Hours Act in Finland outlines regulations for work hours, exemptions, and arrangements such as on-call duty. It applies to employees under various work contracts and aims to ensure fair working hours and conditions, with specific provisions for different sectors and job roles.', 'Finland', 'nature', 'in_force', '2019-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_32', ARRAY['sdg15', 'mandatory', 'finland', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ab489743-cee1-5da2-a6c9-0bb31245b8da', 'Finland Finnish Accounting Act', 'Finnish Accounting Act 2016/1376', 'The Finnish Accounting Act (1336/1997), as amended in 2016 by Act 2016/1376, requires large public interest entities to include material non-financial issues in their annual/financial reports from financial year 2017 onwards. This includes information on environmental matters, social and employee-related matters, respect for human rights, anti-corruption, and bribery. The amendment is intended to reflect the content in the European Commission Directive 2013/34/EU, which states that reporting information "should not be restricted to the financial aspects of the undertaking''s business, and there should be an analysis of environmental and social aspects of the business necessary for an understanding of the undertaking''s development, performance or position.', 'The Finnish Accounting Act (1336/1997), as amended in 2016 by Act 2016/1376, requires large public interest entities to include material non-financial issues in their annual/financial reports from financial year 2017 onwards. This includes information on environmental matters, social and employee-related matters, respect for human rights, anti-corruption, and bribery. The amendment is intended to reflect the content in the European Commission Directive 2013/34/EU, which states that reporting information "should not be restricted to the financial aspects of the undertaking''s business, and there should be an analysis of environmental and social aspects of the business necessary for an understanding of the undertaking''s development, performance or position.', 'The Finnish Accounting Act (1336/1997), as amended in 2016 by Act 2016/1376, requires large public interest entities to include material non-financial issues in their annual/financial reports from financial year 2017 onwards. This includes information on environmental matters, social and employee-related matters, respect for human rights, anti-corruption, and bribery. The amendment is intended to reflect the content in the European Commission Directive 2013/34/EU, which states that reporting information "should not be restricted to the financial aspects of the undertaking''s business, and there should be an analysis of environmental and social aspects of the business necessary for an understanding of the undertaking''s development, performance or position.', 'Finland', 'climate', 'in_force', '2016-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_22', ARRAY['sdg8', 'regulations', 'mandatory', 'sdg16', 'disclosure', 'finland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('cb85a684-4be1-522e-9940-bd022e7f21ab', 'Finland Decree of the Ministry of Finance amending the', 'Decree of the Ministry of Finance amending the Decree of the Ministry of Finance of the regular disclosure obligation of the issuer of a security', 'The Decree of the Ministry of Finance in Finland, effective from January 1, 2017, focuses on amending the regular disclosure obligations of security issuers. It introduces exemptions for small and medium-sized enterprises based on financial thresholds. The decree mandates the presentation of a detailed corporate governance statement by issuers, covering compliance with governance rules, risk management systems, board composition and activities, diversity policies, and their implementation. This policy aligns with Directive 2014/95/EU and aims to enhance transparency and accountability in the securities market.', 'The Decree of the Ministry of Finance in Finland, effective from January 1, 2017, focuses on amending the regular disclosure obligations of security issuers. It introduces exemptions for small and medium-sized enterprises based on financial thresholds. The decree mandates the presentation of a detailed corporate governance statement by issuers, covering compliance with governance rules, risk management systems, board composition and activities, diversity policies, and their implementation. This policy aligns with Directive 2014/95/EU and aims to enhance transparency and accountability in the securities market.', 'The Decree of the Ministry of Finance in Finland, effective from January 1, 2017, focuses on amending the regular disclosure obligations of security issuers. It introduces exemptions for small and medium-sized enterprises based on financial thresholds. The decree mandates the presentation of a detailed corporate governance statement by issuers, covering compliance with governance rules, risk management systems, board composition and activities, diversity policies, and their implementation. This policy aligns with Directive 2014/95/EU and aims to enhance transparency and accountability in the securities market.', 'Finland', 'nature', 'in_force', '2016-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_23', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'sdg15', 'finland']::text[]) ON CONFLICT (id) DO NOTHING;
